TIME_LOSS_IPERF_START_STOP_PROCESS = 0.025  # 25ms for turning ON & OFF iperf process


class BurstMode:
    """Class for handling burst mode in iperf data transfer."""

    def __init__(self, dt_config, iperf_report_parser, logger):
        # Mirror important dt dependency attributes from LteDataTransfer instance
        self.logger = logger
        self.dt_config = dt_config
        self.iperf_report_parser = iperf_report_parser

        self._cycles = None
        self._sleep = float(self.dt_config['robot_kwargs'].get("burst_sleep", TIME_LOSS_IPERF_START_STOP_PROCESS)
                            if 'robot_kwargs' in self.dt_config else TIME_LOSS_IPERF_START_STOP_PROCESS)

    @staticmethod
    def __burst_calc_bits(str_formated_val: str) -> int:
        """Calculate bits from string formatted value."""
        str_formated_val = str_formated_val.upper()
        if str_formated_val.endswith('G'):
            return int(float(str_formated_val[:-1]) * 1024 * 1024 * 1024)
        elif str_formated_val.endswith('M'):
            return int(float(str_formated_val[:-1]) * 1024 * 1024)
        elif str_formated_val.endswith('K'):
            return int(float(str_formated_val[:-1]) * 1024)
        else:
            return int(str_formated_val)

    @property
    def cycles(self) -> int:
        """
        Burst cycles for command with many iperf calls.
        :return: int: number of burst cycles during desired datatransfer duration
        """
        if self._cycles:
            return self._cycles
        dt_duration = float(self.dt_config['duration'])
        bandwidth = self.__burst_calc_bits(self.dt_config['robot_kwargs'].get('bandwidth'))
        buffers = self.__burst_calc_bits(self.dt_config['robot_kwargs'].get('buffers')) * 8
        # Calculate burst cycles, if real duration might be less, add 1 cycle extra
        _burst_duration = buffers / bandwidth + self._sleep  # in Seconds (float)
        self._cycles = int(dt_duration / _burst_duration) + (1 if dt_duration % _burst_duration > 0 else 0)
        return self._cycles

    @property
    def cycle_sleep_duration(self) -> float:
        """
        Calculate real sleep time for burst mode with correction of mean start/stop delays.
        :return: float: sleep time in seconds
        """
        return round(float(self._sleep) - TIME_LOSS_IPERF_START_STOP_PROCESS, 3)

    @property
    def active(self) -> bool:
        """
        Check if burst mode is enabled.
        :return: bool: True if burst mode is enabled
        """
        bandwidth = self.dt_config['robot_kwargs'].get('bandwidth')
        buffers = self.dt_config['robot_kwargs'].get('buffers')
        is_tcp = self.dt_config['protocol'] == 'tcp'
        self.iperf_report_parser.burst = (self._sleep > TIME_LOSS_IPERF_START_STOP_PROCESS and bandwidth and buffers
                                          and is_tcp)
        return self.iperf_report_parser.burst
